// dinput.h link-button suffix bytes (low byte of *_LINK / MENU / PAUSE / DEVICE).
const LINK_LOW_BYTE: Record<number, number> = {
    0xE0: 0xC8, 0xE4: 0xCB, 0xE8: 0xD0, 0xEC: 0xCD, // up/left/down/right
    0xFC: 0x01, 0xFD: 0x01, 0xFE: 0x3C, // pause/menu/device
};
// Priority-1/2 virtual button ordinals (low byte) when name rules miss.
const BUTTON_ORDINAL: Record<number, number> = {
    0x01: 0x39, 0x02: 0x1D, 0x03: 0x2A, 0x04: 0x2E, 0x05: 0x0F, 0x06: 0x3B, 0x07: 0x32, 0x08: 0x19,
    0x09: 0x12, 0x0A: 0x10, 0x0B: 0x13, 0x0C: 0x21, 0x0D: 0x2D, 0x0E: 0x2C, 0x0F: 0x2F, 0x10: 0x1C,
    0x11: 0x03, 0x12: 0x04, 0x13: 0x05, 0x14: 0x06, 0x15: 0x07, 0x16: 0x08, 0x17: 0x09, 0x18: 0x0A,
};
// Virtual axis channel ((semantic >> 16) & 7) for DIAXIS_* when name rules miss.
const AXIS_CHANNEL: Record<number, number> = {
    0: 0xCB, 1: 0xC8, 2: 0xCB, 3: 0xC8, 4: 0xD0, 5: 0xC8, 6: 0xC8, 7: 0xC8,
};

function genericGenreKeyboardDik(sem: number): number | null {
    const low = sem & 0xff;
    const link = LINK_LOW_BYTE[low];
    if (link !== undefined) return link;
    const controlClass = ((sem >>> 8) & 0xff) & 0x0f;
    if (controlClass === 0x06) return 0x10; // DIHATSWITCH_* -> Q
    if (controlClass === 0x02 || controlClass === 0x0a) {
        return AXIS_CHANNEL[(sem >>> 16) & 7] ?? 0xC8;
    }
    if (controlClass === 0x04 || controlClass === 0x0c) {
        return BUTTON_ORDINAL[low] ?? null;
    }
    return null;
}

export function defaultKeyboardDikForSemantic(semantic: number): number | null {
    const sem = semantic >>> 0;
    if (((sem & DI_KEYBOARD_SEMANTIC_MASK) >>> 0) === DI_KEYBOARD_SEMANTIC_TAG) {
        const dik = sem & 0xff;
        return dik !== 0 ? dik : null;
    }
    if (!isGenreSemantic(sem)) return null;
    return DI_KEYBOARD_DEFAULTS[sem] ?? genericGenreKeyboardDik(sem);
}

function isGenreSemantic(sem: number): boolean {
    const hi = sem >>> 24;
    if (hi === 0x81 || hi === 0x82 || hi === 0x83) return false;
    if (hi === 0xff) return false;
    return true;
}

/** Mouse object id for genre / DIMOUSE_* semantics (BuildActionMap on SysMouse). */
export function defaultMouseObjIdForSemantic(semantic: number): number | null {
    const sem = semantic >>> 0;
    if ((sem >>> 24) === DI_MOUSE_SEMANTIC_HI) {
        const ofs = sem & 0xff;
        const mid = (sem >>> 8) & 0xff;
        if (mid === 0x04 || ofs >= 12) return (DIDFT_BUTTON | didftMakeInstance(ofs >= 12 ? ofs - 12 : 0)) >>> 0;
        const inst = ofs === 0 ? 0 : ofs === 8 ? 2 : 1;
        const type = mid === 0x02 ? DIDFT_ABSAXIS : DIDFT_RELAXIS;
        return (type | didftMakeInstance(inst)) >>> 0;
    }
    if (!isGenreSemantic(sem)) return null;
    const low = sem & 0xff;
    const link = LINK_LOW_BYTE[low];
    if (link !== undefined) {
        if (link === 0xCB) return (DIDFT_RELAXIS | didftMakeInstance(0)) >>> 0;
        if (link === 0xCD) return (DIDFT_RELAXIS | didftMakeInstance(0)) >>> 0;
        if (link === 0xC8) return (DIDFT_RELAXIS | didftMakeInstance(1)) >>> 0;
        if (link === 0xD0) return (DIDFT_RELAXIS | didftMakeInstance(1)) >>> 0;
        if (low === 0xFC || low === 0xFD) return (DIDFT_BUTTON | didftMakeInstance(1)) >>> 0;
        return (DIDFT_BUTTON | didftMakeInstance(2)) >>> 0;
    }
    const controlClass = ((sem >>> 8) & 0xff) & 0x0f;
    if (controlClass === 0x02 || controlClass === 0x0a) {
        const ch = (sem >>> 16) & 7;
        const inst = ch === 2 ? 2 : ch === 4 ? 2 : ch & 1;
        return (DIDFT_RELAXIS | didftMakeInstance(inst)) >>> 0;
    }
    if (controlClass === 0x04 || controlClass === 0x0c) {
        const btn = BUTTON_ORDINAL[low];
        const idx = btn !== undefined ? Math.min(4, (low - 1) & 7) : 0;
        return (DIDFT_BUTTON | didftMakeInstance(idx)) >>> 0;
    }
    if (controlClass === 0x06) return (DIDFT_BUTTON | didftMakeInstance(2)) >>> 0;
    return null;
}

/** Gamepad/joystick object id for genre semantics (BuildActionMap on SysJoystick). */
export function defaultGamepadObjIdForSemantic(semantic: number): number | null {
    const sem = semantic >>> 0;
    if (!isGenreSemantic(sem)) return null;
    const low = sem & 0xff;
    const link = LINK_LOW_BYTE[low];
    if (link !== undefined) {
        if (link === 0xCB || link === 0xCD) return (DIDFT_ABSAXIS | didftMakeInstance(0)) >>> 0;
        if (link === 0xC8 || link === 0xD0) return (DIDFT_ABSAXIS | didftMakeInstance(1)) >>> 0;
        return (DIDFT_BUTTON | didftMakeInstance(Math.min(15, low & 0x0f))) >>> 0;
    }
    const controlClass = ((sem >>> 8) & 0xff) & 0x0f;
    if (controlClass === 0x06) return (DIDFT_POV | didftMakeInstance(0)) >>> 0;
    if (controlClass === 0x02 || controlClass === 0x0a) {
        const ch = (sem >>> 16) & 7;
        const inst = ch === 3 ? 2 : ch === 4 ? 3 : ch & 1;
        return (DIDFT_ABSAXIS | didftMakeInstance(inst)) >>> 0;
    }
    if (controlClass === 0x04 || controlClass === 0x0c) {
        const idx = low >= 1 && low <= 0x10 ? low - 1 : 0;
        return (DIDFT_BUTTON | didftMakeInstance(idx)) >>> 0;
    }
    return null;
}

export function isMappableGenreSemantic(semantic: number): boolean {
    const sem = semantic >>> 0;
    return isGenreSemantic(sem);
}
